const $ = id => document.getElementById(id);
const menu=$('menu-toggle');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));$('navigation').classList.toggle('open',open)});
document.querySelectorAll('#navigation a').forEach(a=>a.addEventListener('click',()=>{menu?.setAttribute('aria-expanded','false');$('navigation')?.classList.remove('open')}));
const copy={diagnosis:['Find the moment that mattered.','Follow the request, memory, and tool evidence to the first consequential failure. Keep the references beside the explanation.','Working prototype'],repair:['One change. A clear reason.','Compare permitted repair surfaces against frozen state. Recommend a bounded change, or abstain when one repair cannot solve the problem.','Replay-guided selection'],verification:['Trust the check, not the confidence.','Inspect task success, required invariants, and safety regressions. A plausible explanation never substitutes for a passing replay.','Deterministic verification'],governance:['The final say stays with you.','Approval to test is separate from permission to activate. Keep a record of the decision and revoke a policy when it should stop being used.','Explicit human review']};
function selectCapability(button){document.querySelectorAll('[data-capability]').forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1});const value=copy[button.dataset.capability];$('cap-title').textContent=value[0];$('cap-body').textContent=value[1];$('cap-status').textContent=value[2];$('cap-visual').dataset.active=button.dataset.capability;$('cap-visual').setAttribute('aria-labelledby',button.id)}
document.querySelectorAll('[data-capability]').forEach((button,i,all)=>{button.addEventListener('click',()=>selectCapability(button));button.addEventListener('keydown',event=>{if(!['ArrowDown','ArrowUp','ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();let next=event.key==='Home'?0:event.key==='End'?all.length-1:(i+(event.key==='ArrowDown'||event.key==='ArrowRight'?1:-1)+all.length)%all.length;all[next].focus();selectCapability(all[next])})});
const dialog=$('contact-dialog');
document.querySelectorAll('[data-contact]').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));
$('close-dialog')?.addEventListener('click',()=>dialog.close());
dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
$('contact-form')?.addEventListener('submit',event=>{event.preventDefault();const workflow=$('workflow').value.trim(),challenge=$('challenge').value.trim();const body=`I'd like to explore SuperTuriya for this workflow:\n\n${workflow}\n\nThe failure I want to understand:\n\n${challenge}\n\nI understand SuperTuriya is an early prototype and this is a public discussion.`;window.open('https://github.com/Anirvium/SuperTuriya/issues/new?title='+encodeURIComponent('Design partner conversation')+'&body='+encodeURIComponent(body),'_blank','noopener,noreferrer');dialog.close()});
